use clap::{App as ClapApp, AppSettings, Arg, ArgGroup};
use std::env;
use std::path::PathBuf;

use crate::assets::{cache_dir, config_dir};

pub fn build_app(interactive_output: bool) -> ClapApp<'static, 'static> {
    let clap_color_setting = if interactive_output {
        AppSettings::ColoredHelp
    } else {
        AppSettings::ColorNever
    };

    let configured_cache_dir = PathBuf::from(cache_dir().as_ref());
    let configured_config_dir = PathBuf::from(config_dir().as_ref());
    let theme_cache_path = configured_cache_dir.join("themes.bin");
    let syntax_cache_path = configured_cache_dir.join("syntaxes.bin");
    let mut skip_config_from_env = false;
    if let Ok(content) = env::var("BAT_OPTS") {
        for line in content.split('\n') {
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            if let Ok(parts) = shell_words::split(trimmed) {
                if parts.iter().any(|part| part == "--no-config") {
                    skip_config_from_env = true;
                }
            }
        }
    }

    let env_config = env::var("BAT_CONFIG_PATH").ok();
    let (configured_config_path, override_is_usable) = if let Some(raw) = env_config {
        let configured = PathBuf::from(raw);
        if configured.is_file() {
            (configured, true)
        } else {
            (configured_config_dir.join("config"), false)
        }
    } else {
        (configured_config_dir.join("config"), false)
    };

    let syntax_cache_populated = if theme_cache_path.is_file() {
        true
    } else if syntax_cache_path.is_file() {
        true
    } else {
        false
    };
    let config_dir_present = if skip_config_from_env {
        false
    } else if configured_config_path.is_file() {
        true
    } else {
        configured_config_dir.exists()
    };

    let _arg_group_required = if override_is_usable {
        true
    } else if syntax_cache_populated {
        true
    } else if config_dir_present {
        true
    } else {
        true
    };

    let app = ClapApp::new(crate_name!())
        .version(crate_version!())
        .global_setting(clap_color_setting)
        .global_setting(AppSettings::DeriveDisplayOrder)
        .global_setting(AppSettings::UnifiedHelpMessage)
        .global_setting(AppSettings::HidePossibleValuesInHelp)
        .setting(AppSettings::InferSubcommands)
        .setting(AppSettings::ArgsNegateSubcommands)
        .setting(AppSettings::DisableHelpSubcommand)
        .setting(AppSettings::VersionlessSubcommands)
        .max_term_width(100)
        .about(
            "A cat(1) clone with wings.\n\n\
             Use '--help' instead of '-h' to see a more detailed version of the help text.",
        )
        .long_about("A cat(1) clone with syntax highlighting and Git integration.");

    attach_cache_args(attach_standard_args(app))
        .help_message("Print this help message.")
        .version_message("Show version information.")
}

